'use strict';

// MODULES //

var max = require( '@stdlib/math/base/special/max' );
var isInteger = require( '@stdlib/assert/is-integer' ).isPrimitive;
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var validate = require( './validate.js' );


// MAIN //

/**
* Creates one public validation contract around a normalized backend.
* @private
* @param {Function} backend - normalized routine
* @param {Function} [eligible] - optional native eligibility
* @param {Function} [fallback] - validated fallback
* @returns {Function} public routine
*/
function factory( backend, eligible, fallback ) {
	setReadOnly( dpbtf2, 'ndarray', ndarray );
	return dpbtf2;

	/**
* Factors compact band storage using a contiguous layout.
* @private
* @param {string|integer} order - storage layout
* @param {string|integer} uplo - selected triangle
* @param {NonNegativeInteger} N - matrix order
* @param {NonNegativeInteger} KD - bandwidth
* @param {Float64Array} AB - compact band storage
* @param {PositiveInteger} LDAB - leading dimension
* @throws {TypeError} invalid argument
* @throws {RangeError} invalid argument
* @returns {integer} INFO
*/
	function dpbtf2( order, uplo, N, KD, AB, LDAB ) {
		var column;
		var shape;
		if ( ((((order !== 'row-major') && (order !== 'column-major')) && (order !== 101)) && (order !== 102)) ) {
			throw new TypeError( 'invalid argument. Invalid layout.' );
		}
		shape = validate.scalars( uplo, N, KD );
		validate.integer( LDAB );
		column = ((order === 'column-major') || (order === 102));
		if ( (LDAB < (( column ) ? shape.h : max(1, N))) ) {
			throw new RangeError( 'invalid argument. Invalid leading dimension.' );
		}
		if ( shape.empty ) {
			return 0;
		}
		return ndarray( shape.uplo, N, KD, AB, ( column ) ? 1 : LDAB, ( column ) ? LDAB : 1, 0 );
	}
	/**
* Factors a full injective signed band view.
* @private
* @param {string|integer} uplo - selected triangle
* @param {NonNegativeInteger} N - matrix order
* @param {NonNegativeInteger} KD - bandwidth
* @param {Float64Array} AB - compact band storage
* @param {integer} r - band row stride
* @param {integer} c - band column stride
* @param {integer} o - band offset
* @throws {TypeError} invalid argument
* @throws {RangeError} invalid argument
* @returns {integer} INFO
*/
	function ndarray( uplo, N, KD, AB, r, c, o ) {
		var shape;
		var info;
		var use;
		shape = validate.scalars( uplo, N, KD );
		if ( shape.empty ) {
			return 0;
		}
		validate( shape.h, N, AB, r, c, o );
		r = ( (shape.h === 1) ) ? 1 : r;
		c = ( (N === 1) ) ? 1 : c;
		use = ( (eligible && !eligible(shape.uplo, N, KD, AB, r, c, o)) ) ? fallback : backend;
		info = use( shape.uplo, N, KD, AB, r, c, o );
		if ( ((!isInteger(info) || (info < 0)) || (info > N)) ) {
			throw new RangeError( 'invalid argument. Private INFO is outside the scalar status domain.' );
		}
		return info;
	}
}


// EXPORTS //

module.exports = factory;
